function answeredByPush(latestAsk: AnswerableAsk | undefined, headCommittedAt: string | undefined): AskAuthor | undefined {
  if (!latestAsk || !latestAsk.at || !headCommittedAt) return undefined;
  const askAt = Date.parse(latestAsk.at);
  const commitAt = Date.parse(headCommittedAt);
  if (Number.isNaN(askAt) || Number.isNaN(commitAt)) return undefined;
  if (commitAt <= askAt) return undefined;
  return latestAsk.author;
}
```

